head.script:
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.vPRELM_INVSTG_BZ_PROCS_NO;
scwin.vListProcsStatCd;
scwin.TR_JOB;
scwin.mktTpCd; // 거래시장구분 1= 유가, 2=코스닥

// var gAfStdIndCd = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Item);
        let parentWin = $c.frame.path("../");
        scwin.vBzProcsNo = parentWin.scwin.vBzProcsNo;
        scwin.vListProcsStatCd = parentWin.scwin.vListProcsStatCd;
        scwin.vPRELM_INVSTG_BZ_PROCS_NO = parentWin.scwin.vPRELM_INVSTG_BZ_PROCS_NO;
        scwin.mktTpCd = parentWin.scwin.mktTpCd;

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정

        // alert("vBzProcsNo :"+vBzProcsNo);
        if (scwin.vBzProcsNo !== "") {
            await scwin.readSync();
        } else {
            const sbmOptions = {
                id : "sbm_dts_Item",
                action : "/gauceSystemierAdaptor.do",
                ref : "",
                target : "dts_Item=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            dts_Item.insertRow();
        }
        scwin.initForm();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05106.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Item_OnLoadError
 * @description dts_Item 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Item_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Item);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05106.dts_Item_OnLoadError" });
    }
};

/**
 * @method
