///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    // alert("LST_LM_CD :"+LST_LM_CD);
    dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_Item",
        action : "/KindStk.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dts_Item.getCellData(1, "BZ_PROCS_NO") === '') {
        buttonSet.setInsertStatus();
        url += "&BZ_PROCS_NO=" + scwin.vPRELM_INVSTG_BZ_PROCS_NO;
        const sbmOptions = {
            id : "sbm_dts_Item",
            action : "/KindStk.do",
            ref : "",
            target : "dts_Item=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        if (dts_Item.getCellData(1, "BZ_PROCS_NO") !== '') {
            dts_Item.setCellData('1', "BZ_PROCS_NO", '');
        } else {
            const sbmOptions = {
                id : "sbm_dts_Item",
                action : "/gauceSystemierAdaptor.do",
                ref : "",
                target : "dts_Item=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            dts_Item.insertRow();
        }
    } else {
        buttonSet.setUpdateStatus();
    }
};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function() {
    let vScrenProcTpCd;
    if (scwin.TR_JOB === "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB === "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    }
    //        dts_Item.NameValue(1, "BZ_PROCS_NO") = vBzProcsNo;

    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/KindStk.do",
        ref : "dts_Item",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initForm
 * @description ********************************************************************
 * @returns {void}
 * @hidden N
 */
scwin.initForm = function() {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

    if (dts_Item.getCellData(1, "ACCTP_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "ACCTP_YN") == '') dts_Item.NameValue(1, "ACCTP_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "CASH_DIV_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "CASH_DIV_YN") == '') dts_Item.NameValue(1, "CASH_DIV_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "CMSTK_PCT1_DIV_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "CMSTK_PCT1_DIV_YN") == '') dts_Item.NameValue(1, "CMSTK_PCT1_DIV_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "COM_CASH_REDMPT_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "COM_CASH_REDMPT_YN") == '') dts_Item.NameValue(1, "COM_CASH_REDMPT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "COM_CONV_RGHT_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "COM_CONV_RGHT_YN") == '') dts_Item.NameValue(1, "COM_CONV_RGHT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "COM_REDMPT_RGHT_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "COM_REDMPT_RGHT_YN") == '') dts_Item.NameValue(1, "COM_REDMPT_RGHT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "CONV_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "CONV_YN") == '') dts_Item.NameValue(1, "CONV_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "LWST_DIV_RT_DSC_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "LWST_DIV_RT_DSC_YN") == '') dts_Item.NameValue(1, "LWST_DIV_RT_DSC_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "MISC_DIV_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "MISC_DIV_YN") == '') dts_Item.NameValue(1, "MISC_DIV_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "NDIVTM_VOTERGHT_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "NDIVTM_VOTERGHT_YN") == '') dts_Item.NameValue(1, "NDIVTM_VOTERGHT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "PARTCTP_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "PARTCTP_YN") == '') dts_Item.NameValue(1, "PARTCTP_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "PROFT_DIV_REMK") === '') /*ORG SRC: if (dts_Item.NameValue(1, "PROFT_DIV_REMK") == '') dts_Item.NameValue(1, "PROFT_DIV_REMK") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "PROFT_DIV_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "PROFT_DIV_YN") == '') dts_Item.NameValue(1, "PROFT_DIV_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "REDMPT_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "REDMPT_YN") == '') dts_Item.NameValue(1, "REDMPT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "REMAIN_PROPRT_DISTR_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "REMAIN_PROPRT_DISTR_YN") == '') dts_Item.NameValue(1, "REMAIN_PROPRT_DISTR_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "SHRHD_CASH_REDMPT_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "SHRHD_CASH_REDMPT_YN") == '') dts_Item.NameValue(1, "SHRHD_CASH_REDMPT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "SHRHD_CONV_RGHT_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "SHRHD_CONV_RGHT_YN") == '') dts_Item.NameValue(1, "SHRHD_CONV_RGHT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "SHRHD_REDMPT_RGHT_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "SHRHD_REDMPT_RGHT_YN") == '') dts_Item.NameValue(1, "SHRHD_REDMPT_RGHT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "VOTERGHT_EXCLD_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "VOTERGHT_EXCLD_YN") == '') dts_Item.NameValue(1, "VOTERGHT_EXCLD_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "VOTERGHT_LMT_YN") === '') /*ORG SRC: if (dts_Item.NameValue(1, "VOTERGHT_LMT_YN") == '') dts_Item.NameValue(1, "VOTERGHT_LMT_YN") = 0;*/ X = 0;
    if (dts_Item.getCellData(1, "PROFT_DIV_YN") === "1") {
        panel_1.show("");
    } else {
        panel_1.hide();
    }
    if (dts_Item.getCellData(1, "REMAIN_PROPRT_DISTR_YN") === 1) {
        panel_2.show("");
    } else {
        panel_2.hide();
    }
    if (dts_Item.getCellData(1, "VOTERGHT_EXCLD_YN") === 1) {
        panel_3.show("");
    } else {
        panel_3.hide();
    }
    if (dts_Item.getCellData(1, "VOTERGHT_LMT_YN") === 1) {
        panel_4.show("");
    } else {
        panel_4.hide();
    }
    if (dts_Item.getCellData(1, "REDMPT_YN") === 1) {
        if (dts_Item.getCellData(1, "COM_REDMPT_RGHT_YN") === 1) {
            panel_6.show("");
        } else {
            panel_6.hide();
        }
        if (dts_Item.getCellData(1, "SHRHD_REDMPT_RGHT_YN") === 1) {
            panel_7.show("");
        } else {
            panel_7.hide();
        }
        panel_5.show("");
    } else {
        panel_6.hide();
        panel_7.hide();
        panel_5.hide();
    }
    if (dts_Item.getCellData(1, "CONV_YN") === 1) {
        if (dts_Item.getCellData(1, "COM_CONV_RGHT_YN") === 1) {
            panel_9.show("");
