        if (dts_Item.getCellData(1, "SHRHD_CONV_RGHT_YN") === 1) {
            panel_10.show("");
        } else {
            panel_10.hide();
        }
        panel_8.show("");
    } else {
        panel_9.hide();
        panel_10.hide();
        panel_8.hide();
    }
};

